  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
]);
const digestHourUtcSchema = z.number().int().min(0).max(23);
const enabledFlagOverridesSchema = z.array(z.string());

export const organizationSettingsSchema = z.object({
  defaultIssueStatus: defaultIssueStatusSchema.default("backlog"),
  allowPublicProjects: z.boolean().default(false),
  requireTwoFactor: z.boolean().default(false),
  digestHourUtc: digestHourUtcSchema.default(7),
  enabledFlagOverrides: enabledFlagOverridesSchema.default([]),
});

/**
 * Update patch. Built without `.default()`: in Zod 4, `.partial()` on a
 * defaulted object still fills every omitted key, so a one-field save would
 * wipe the rest of the stored settings (including `0`, `false`, and `[]`).
 */
export const organizationSettingsPatchSchema = z
  .object({
    defaultIssueStatus: defaultIssueStatusSchema,
    allowPublicProjects: z.boolean(),
    requireTwoFactor: z.boolean(),
    digestHourUtc: digestHourUtcSchema,
    enabledFlagOverrides: enabledFlagOverridesSchema,
  })
  .partial();

