import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { updateOrganizationSchema } from "@/schemas/organization";
import * as orgRepo from "@/server/repositories/organization-repository";
import { updateOrganization } from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("organization settings patch", () => {
  it("changes only submitted settings, including 0, false, and []", async () => {
    const a = await createTenant("alpha", "starter");
    const b = await createTenant("beta", "starter");

    await orgRepo.updateOrg(a.org.id, {
      orgId: a.org.id,
      settings: {
        digestHourUtc: 18,
        requireTwoFactor: true,
        enabledFlagOverrides: ["digest_email", "activity_feed"],
        defaultIssueStatus: "todo",
      },
    });
    await orgRepo.updateOrg(b.org.id, {
      orgId: b.org.id,
      settings: {
        digestHourUtc: 18,
        requireTwoFactor: true,
        enabledFlagOverrides: ["digest_email"],
        allowPublicProjects: false,
      },
    });

    const parsed = updateOrganizationSchema.parse({
      orgId: a.org.id,
      settings: { defaultIssueStatus: "in_progress" },
    });
    expect(parsed.settings).toEqual({ defaultIssueStatus: "in_progress" });

    const updated = await updateOrganization(a.actors.admin, parsed);
    expect(updated.settings).toEqual({
      defaultIssueStatus: "in_progress",
      allowPublicProjects: false,
      requireTwoFactor: true,
      digestHourUtc: 18,
      enabledFlagOverrides: ["digest_email", "activity_feed"],
    });

    const cleared = await updateOrganization(a.actors.admin, {
      orgId: a.org.id,
      settings: {
        allowPublicProjects: true,
        digestHourUtc: 0,
        requireTwoFactor: false,
        enabledFlagOverrides: [],
      },
    });
    expect(cleared.settings.allowPublicProjects).toBe(true);
    expect(cleared.settings.digestHourUtc).toBe(0);
    expect(cleared.settings.requireTwoFactor).toBe(false);
    expect(cleared.settings.enabledFlagOverrides).toEqual([]);
    expect(cleared.settings.defaultIssueStatus).toBe("in_progress");

    const renamed = await updateOrganization(a.actors.admin, {
      orgId: a.org.id,
      name: "Alpha renamed",
    });
    expect(renamed.name).toBe("Alpha renamed");
    expect(renamed.settings).toEqual(cleared.settings);

    const other = await orgRepo.findOrgById(b.org.id);
    expect(other?.settings).toEqual({
      defaultIssueStatus: "backlog",
      allowPublicProjects: false,
      requireTwoFactor: true,
      digestHourUtc: 18,
      enabledFlagOverrides: ["digest_email"],
    });
  });
});

